    """Return the 3x3 panel containing the greatest number of non-background colors."""
    h, w = len(grid), len(grid[0])
    best = None
    best_colors = -1
    for r in range(h - 2):
        for c in range(w - 2):
            block = [row[c:c + 3] for row in grid[r:r + 3]]
            colors = {v for row in block for v in row if v != 0}
